const seen = {};
const out = [];
$input.all().forEach((item) => {
  const o = item.json;
  const orderId = String(o.orderId || '').trim();
  if (!orderId || seen[orderId]) {
    return;
  }
  seen[orderId] = true;
  const items = (o.items || []).filter((it) => it && it.sku && it.qty > 0 && it.price > 0);
  const subtotal = items.reduce((t, it) => t + it.qty * it.price, 0);
  out.push({ json: { orderId: orderId, customerId: o.customerId, customerName: o.customerName, accountAgeDays: o.accountAgeDays, lifetimeSpend: o.lifetimeSpend, city: o.city, lat: o.lat, lng: o.lng, billingCountry: o.billingCountry, shippingCountry: o.shippingCountry, payment: o.payment, speed: o.speed, coupon: o.coupon || '', hour: o.hour, items: items, subtotal: subtotal, rejected: items.length === 0 } });
});
return out;

const all = $input.all().map((x) => x.json);
const valid = all.filter((o) => !o.rejected);
const mean = valid.length ? valid.reduce((t, o) => t + o.subtotal, 0) / valid.length : 0;
const variance = valid.length ? valid.reduce((t, o) => t + Math.pow(o.subtotal - mean, 2), 0) / valid.length : 0;
const std = Math.sqrt(variance);
const perCustomer = {};
all.forEach((o) => {
  perCustomer[o.customerId] = (perCustomer[o.customerId] || 0) + 1;
});
return all.map((o) => {
  if (o.rejected) {
    return { json: Object.assign({}, o, { fraudScore: 0, fraudLevel: 'Rejected', fraudReasons: ['No valid items'], route: 'hold' }) };
  }
  let score = 0;
  const reasons = [];
  if (o.accountAgeDays < 7) {
    score += 2;
    reasons.push('New account');
  }
  if (o.subtotal >= 100000) {
    score += 2;
    reasons.push('Very high order value');
  }
  if (o.payment === 'COD' && o.subtotal > 20000) {
    score += 1;
    reasons.push('High value cash on delivery');
  }
  if (o.billingCountry !== o.shippingCountry) {
    score += 2;
    reasons.push('Billing and shipping country differ');
  }
  if (o.hour >= 1 && o.hour <= 4) {
    score += 1;
    reasons.push('Night-time order');
  }
  if (perCustomer[o.customerId] >= 2) {
    score += 1;
    reasons.push('Multiple orders in one batch');
  }
  if (o.items.some((it) => it.qty >= 10)) {
    score += 1;
    reasons.push('Bulk quantity');
  }
  const z = std > 0 ? (o.subtotal - mean) / std : 0;
  if (z > 2) {
    score += 1;
    reasons.push('Unusual order value (z=' + z.toFixed(1) + ')');
  }
  let level = 'Clear';
  if (score >= 5) {
    level = 'Block';
  } else if (score >= 3) {
    level = 'Review';
  }
  return { json: Object.assign({}, o, { fraudScore: score, fraudLevel: level, fraudReasons: reasons, route: level === 'Block' ? 'hold' : 'process' }) };
});

return $input.all().map((item) => {
  const o = item.json;
  const rejected = o.fraudLevel === 'Rejected';
  const reason = rejected ? 'No valid items in order' : 'Fraud score ' + o.fraudScore + ': ' + o.fraudReasons.join(', ');
  const action = rejected ? 'Reject order and ask the customer to resubmit' : 'Block shipment and contact the customer for verification';
  return { json: { orderId: o.orderId, customer: o.customerName, valueAtRisk: o.subtotal, reason: reason, action: action } };
});

const coupons = {
  SAVE10: { type: 'percent', value: 10, cap: 500, min: 1000, tiers: [] },
  FLAT200: { type: 'flat', value: 200, cap: 200, min: 1500, tiers: [] },
  VIP15: { type: 'percent', value: 15, cap: 5000, min: 5000, tiers: ['Gold', 'Platinum'] }
};
const tierOf = (spend) => (spend >= 100000 ? 'Platinum' : (spend >= 50000 ? 'Gold' : (spend >= 20000 ? 'Silver' : 'Bronze')));
const tierPct = { Bronze: 0, Silver: 1, Gold: 3, Platinum: 5 };
const tierMult = { Bronze: 1, Silver: 2, Gold: 3, Platinum: 4 };
return $input.all().map((item) => {
  const o = item.json;
  const tier = tierOf(o.lifetimeSpend);
  let couponDiscount = 0;
  let couponNote = 'No coupon';
  if (o.coupon) {
    const c = coupons[o.coupon];
    if (!c) {
      couponNote = 'Invalid coupon ' + o.coupon;
    } else if (o.subtotal < c.min) {
      couponNote = o.coupon + ' needs a minimum of Rs ' + c.min;
    } else if (c.tiers.length > 0 && c.tiers.indexOf(tier) === -1) {
      couponNote = o.coupon + ' is only for ' + c.tiers.join(' or ') + ' members';
    } else {
      couponDiscount = c.type === 'percent' ? Math.min(Math.round(o.subtotal * c.value / 100), c.cap) : c.value;
      couponNote = o.coupon + ' applied';
    }
  }
  const afterCoupon = o.subtotal - couponDiscount;
  const loyaltyDiscount = Math.round(afterCoupon * tierPct[tier] / 100);
  const taxable = afterCoupon - loyaltyDiscount;
  const gst = Math.round(taxable * 0.18);
  const itemsTotal = taxable + gst;
  const loyaltyPoints = Math.floor(itemsTotal / 100) * tierMult[tier];
  return { json: Object.assign({}, o, { tier: tier, couponDiscount: couponDiscount, couponNote: couponNote, loyaltyDiscount: loyaltyDiscount, taxable: taxable, gst: gst, itemsTotal: itemsTotal, loyaltyPoints: loyaltyPoints }) };
});

const rank = { Platinum: 0, Gold: 1, Silver: 2, Bronze: 3 };
const items = $input.all();
items.sort((a, b) => ((a.json.speed === 'express' ? 0 : 1) - (b.json.speed === 'express' ? 0 : 1)) || (rank[a.json.tier] - rank[b.json.tier]) || (a.json.orderId < b.json.orderId ? -1 : 1));
return items.map((it, idx) => ({ json: Object.assign({}, it.json, { priorityRank: idx + 1 }) }));

const setup = $('Warehouse Setup').first().json;
const stock = {};
setup.warehouses.forEach((w) => {
  stock[w.id] = Object.assign({}, w.stock);
});
const toRad = (d) => d * Math.PI / 180;
const km = (lat1, lng1, lat2, lng2) => {
  const R = 6371;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) * Math.sin(dLng / 2);
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
};
return $input.all().map((item) => {
  const o = item.json;
  const ranked = setup.warehouses.map((w) => ({ id: w.id, city: w.city, distance: Math.round(km(o.lat, o.lng, w.lat, w.lng)) })).sort((a, b) => a.distance - b.distance);
  const allocations = [];
  let totalQty = 0;
  let backorderQty = 0;
  o.items.forEach((it) => {
    let need = it.qty;
    totalQty += it.qty;
    ranked.forEach((w) => {
      if (need <= 0) {
        return;
      }
      const have = stock[w.id][it.sku] || 0;
      const take = Math.min(have, need);
      if (take > 0) {
        stock[w.id][it.sku] = have - take;
        need -= take;
        allocations.push({ sku: it.sku, qty: take, warehouse: w.id, city: w.city, distance: w.distance });
      }
    });
    if (need > 0) {
      backorderQty += need;
      allocations.push({ sku: it.sku, qty: need, warehouse: 'BACKORDER', city: '-', distance: 0 });
    }
  });
  const status = backorderQty === 0 ? 'Full' : (backorderQty === totalQty ? 'Backorder' : 'Partial');
  return { json: Object.assign({}, o, { allocations: allocations, backorderQty: backorderQty, fulfillmentStatus: status }) };
});

const setup = $('Warehouse Setup').first().json;
const baseFee = (d) => (d <= 300 ? 60 : (d <= 800 ? 100 : 150));
const perKg = (d) => (d <= 300 ? 40 : (d <= 800 ? 70 : 110));
return $input.all().map((item) => {
  const o = item.json;
  const groups = {};
  o.allocations.forEach((a) => {
    if (a.warehouse === 'BACKORDER') {
      return;
    }
    if (!groups[a.warehouse]) {
      groups[a.warehouse] = { warehouse: a.warehouse, city: a.city, distance: a.distance, weightKg: 0, units: 0 };
    }
    groups[a.warehouse].weightKg += setup.catalog[a.sku].weightKg * a.qty;
    groups[a.warehouse].units += a.qty;
  });
  const shipments = Object.keys(groups).map((k) => {
    const g = groups[k];
    const weight = Math.round(g.weightKg * 100) / 100;
    let cost = baseFee(g.distance) + Math.ceil(weight) * perKg(g.distance);
    if (o.speed === 'express') {
      cost = Math.round(cost * 1.8);
    }
    const days = Math.max(1, Math.ceil(g.distance / 500) + 1 - (o.speed === 'express' ? 1 : 0));
    return { warehouse: g.warehouse, from: g.city, distance: g.distance, units: g.units, weightKg: weight, cost: cost, etaDays: days };
  });
  const carrierCost = shipments.reduce((t, s) => t + s.cost, 0);
  const freeShipping = o.tier === 'Platinum' || o.tier === 'Gold' || o.itemsTotal >= 3000;
  const shippingFee = freeShipping ? 0 : carrierCost;
  const grandTotal = o.itemsTotal + shippingFee;
  const etaDays = shipments.length ? Math.max.apply(null, shipments.map((s) => s.etaDays)) : null;
  return { json: Object.assign({}, o, { shipments: shipments, carrierCost: carrierCost, freeShipping: freeShipping, shippingFee: shippingFee, grandTotal: grandTotal, etaDays: etaDays }) };
});

let seq = 5000;
return $input.all().map((item) => {
  const o = item.json;
  const labels = o.shipments.map((s) => {
    seq += 1;
    return { trackingId: 'TRK' + seq + '-' + s.warehouse, from: s.from, units: s.units, weightKg: s.weightKg, etaDays: s.etaDays };
  });
  const hold = o.fraudLevel === 'Review';
  return { json: { orderId: o.orderId, customer: o.customerName, action: hold ? 'HOLD for manual fraud review, then ship' : 'SHIP NOW', labels: labels, grandTotal: o.grandTotal } };
});

return $input.all().map((item) => {
  const o = item.json;
  const shipNowUnits = o.allocations.filter((a) => a.warehouse !== 'BACKORDER').reduce((t, a) => t + a.qty, 0);
  const premium = o.tier === 'Gold' || o.tier === 'Platinum';
  const offer = premium ? 'Free express upgrade on the backordered items' : 'Offer 5 percent coupon SORRY5 for the delay';
  return { json: { orderId: o.orderId, customer: o.customerName, status: o.fulfillmentStatus, shipNowUnits: shipNowUnits, backorderUnits: o.backorderQty, restockEta: '7 days', offer: offer } };
});

return $input.all().map((item) => {
  const o = item.json;
  let message = '';
  if (o.fraudLevel === 'Review') {
    message = 'Hi ' + o.customerName + ', we are verifying your order ' + o.orderId + ' for security. We will update you within 24 hours.';
  } else if (o.fulfillmentStatus === 'Full') {
    message = 'Hi ' + o.customerName + ', order ' + o.orderId + ' is confirmed. Total Rs ' + o.grandTotal + ', arriving in ' + o.etaDays + ' day(s). You earned ' + o.loyaltyPoints + ' points.';
  } else if (o.fulfillmentStatus === 'Partial') {
    message = 'Hi ' + o.customerName + ', part of order ' + o.orderId + ' ships now (' + o.etaDays + ' day(s)). ' + o.backorderQty + ' item(s) will follow in about 7 days.';
  } else {
    message = 'Hi ' + o.customerName + ', order ' + o.orderId + ' is waiting for stock (about 7 days). You can cancel anytime for a full refund.';
  }
  return { json: Object.assign({}, o, { message: message }) };
});

const setup = $('Warehouse Setup').first().json;
const used = {};
$('Allocate Inventory').all().forEach((x) => {
  x.json.allocations.forEach((a) => {
    if (a.warehouse === 'BACKORDER') {
      return;
    }
    used[a.warehouse] = used[a.warehouse] || {};
    used[a.warehouse][a.sku] = (used[a.warehouse][a.sku] || 0) + a.qty;
  });
});
const warehouses = [];
const alerts = [];
setup.warehouses.forEach((w) => {
  let startUnits = 0;
  let usedUnits = 0;
  Object.keys(w.stock).forEach((sku) => {
    const u = (used[w.id] && used[w.id][sku]) || 0;
    const left = w.stock[sku] - u;
    startUnits += w.stock[sku];
    usedUnits += u;
    if (left <= 2) {
      alerts.push('LOW STOCK ' + w.id + ' ' + sku + ': ' + left + ' left, reorder ' + (10 - left));
    }
  });
  warehouses.push({ warehouse: w.id, city: w.city, startUnits: startUnits, usedUnits: usedUnits, leftUnits: startUnits - usedUnits, utilizationPct: Math.round(usedUnits * 100 / startUnits) });
});
return [{ json: { warehouses: warehouses, alerts: alerts } }];

const util = $input.first().json;
const processed = $('Shipping Plan').all().map((x) => x.json);
const all = $('Fraud Check').all().map((x) => x.json);
const held = all.filter((o) => o.route === 'hold');
const sum = (arr, k) => arr.reduce((t, o) => t + (o[k] || 0), 0);
const count = (arr, fn) => {
  const r = {};
  arr.forEach((o) => {
    const key = fn(o);
    r[key] = (r[key] || 0) + 1;
  });
  return r;
};
const fmt = (obj) => Object.keys(obj).map((k) => k + ': ' + obj[k]).join(', ');
const revenue = sum(processed, 'grandTotal');
const shippingCollected = sum(processed, 'shippingFee');
const carrierCost = sum(processed, 'carrierCost');
const couponSavings = sum(processed, 'couponDiscount');
const loyaltySavings = sum(processed, 'loyaltyDiscount');
const points = sum(processed, 'loyaltyPoints');
const heldValue = sum(held, 'subtotal');
const avgOrder = processed.length ? Math.round(revenue / processed.length) : 0;
const byStatus = count(processed, (o) => o.fulfillmentStatus);
const byFraud = count(all, (o) => o.fraudLevel);
const byTier = count(processed, (o) => o.tier);
const skuUnits = {};
processed.forEach((o) => {
  o.allocations.forEach((a) => {
    if (a.warehouse !== 'BACKORDER') {
      skuUnits[a.sku] = (skuUnits[a.sku] || 0) + a.qty;
    }
  });
});
const topSkus = Object.keys(skuUnits).sort((a, b) => skuUnits[b] - skuUnits[a]).slice(0, 3).map((k) => k + ' (' + skuUnits[k] + ')');
const slaRisk = processed.filter((o) => o.speed === 'express' && (o.fulfillmentStatus !== 'Full' || o.etaDays > 2)).map((o) => o.orderId);
const fulfillRate = processed.length ? Math.round(100 * (byStatus.Full || 0) / processed.length) : 0;
const summary = [
  '📦 Fulfillment Dashboard',
  'Orders received: ' + all.length + ' | processed: ' + processed.length + ' | on hold: ' + held.length,
  'Revenue (incl. tax and shipping): Rs ' + revenue,
  'Average order value: Rs ' + avgOrder,
  'Value held back by fraud checks: Rs ' + heldValue,
  'Shipping collected: Rs ' + shippingCollected + ' vs carrier cost: Rs ' + carrierCost,
  'Coupon savings: Rs ' + couponSavings + ' | loyalty savings: Rs ' + loyaltySavings + ' | points issued: ' + points,
  'Fraud results: ' + fmt(byFraud),
  'Fulfillment: ' + fmt(byStatus) + ' (full rate ' + fulfillRate + ' percent)',
  'Customer tiers: ' + fmt(byTier),
  'Top SKUs: ' + (topSkus.length ? topSkus.join(', ') : 'none'),
  'Express orders at SLA risk: ' + (slaRisk.length ? slaRisk.join(', ') : 'none')
].join('\n');
return [{ json: { received: all.length, processed: processed.length, held: held.length, revenue: revenue, avgOrder: avgOrder, fulfillRate: fulfillRate, warehouses: util.warehouses, alerts: util.alerts, summary: summary } }];

const d = $input.first().json;
const processed = $('Shipping Plan').all().map((x) => x.json);
const held = $('Fraud Check').all().map((x) => x.json).filter((o) => o.route === 'hold');
const orderRows = processed.map((o) => '| ' + o.orderId + ' | ' + o.customerName + ' | ' + o.tier + ' | ' + o.fraudLevel + ' | ' + o.fulfillmentStatus + ' | ' + o.shipments.map((s) => s.from).join(' + ') + ' | ' + (o.etaDays === null ? '-' : o.etaDays + 'd') + ' | Rs ' + o.grandTotal + ' |');
const holdRows = held.map((o) => '| ' + o.orderId + ' | ' + o.customerName + ' | ' + o.fraudLevel + ' | ' + o.fraudScore + ' | ' + o.fraudReasons.join(', ') + ' |');
const whRows = d.warehouses.map((w) => '| ' + w.warehouse + ' | ' + w.city + ' | ' + w.startUnits + ' | ' + w.usedUnits + ' | ' + w.leftUnits + ' | ' + w.utilizationPct + '% |');
const alertLines = d.alerts.length ? d.alerts.map((a) => '- ' + a) : ['- none'];
const report = [
  '# Order Fulfillment Engine Report (demo data)',
  '',
  d.summary,
  '',
  '## Orders processed (priority order)',
  '| Order | Customer | Tier | Fraud | Fulfillment | Ships from | ETA | Total |',
  '|---|---|---|---|---|---|---|---|'
].concat(orderRows).concat(['', '## Orders on hold', '| Order | Customer | Level | Score | Reasons |', '|---|---|---|---|---|']).concat(holdRows).concat(['', '## Warehouses', '| ID | City | Start | Used | Left | Utilization |', '|---|---|---|---|---|---|']).concat(whRows).concat(['', '## Stock alerts']).concat(alertLines).join('\n');
return [{ json: { processed: processed.length, held: held.length, report: report } }];
